<?php
 namespace QQWorld\Framework\View\Page\Config\Reader; use QQWorld\Framework\View\Layout; use QQWorld\Framework\View\Page\Config as PageConfig; class Body implements Layout\ReaderInterface { const TYPE_BODY = 'body'; const BODY_ATTRIBUTE = 'attribute'; protected $readerPool; public function __construct(Layout\ReaderPool $readerPool) { $this->readerPool = $readerPool; } public function getSupportedNodes() { return [self::TYPE_BODY]; } public function interpret( Layout\Reader\Context $readerContext, Layout\Element $bodyElement ) { foreach ($bodyElement as $element) { if ($element->getName() === self::BODY_ATTRIBUTE) { $this->setBodyAttributeToStructure($readerContext, $element); } } $this->readerPool->interpret($readerContext, $bodyElement); return $this; } protected function setBodyAttributeToStructure(Layout\Reader\Context $readerContext, Layout\Element $element) { if ($element->getAttribute('name') == PageConfig::BODY_ATTRIBUTE_CLASS) { $readerContext->getPageConfigStructure()->setBodyClass($element->getAttribute('value')); } else { $readerContext->getPageConfigStructure()->setElementAttribute( PageConfig::ELEMENT_TYPE_BODY, $element->getAttribute('name'), $element->getAttribute('value') ); } return $this; } } 